{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "In healthy volunteers, the 1500 mg tablet of GSK1322322 (a piperazine-aniline-azine inhibitor) had 77% absolute oral bioavailability in the fed state, directly exceeding the 20% threshold; the high transfer score and shared ionizable piperazine/azine core support high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Linezolid, a polar small molecule with multiple H-bond acceptors, has almost 100% oral bioavailability in fasted healthy volunteers, demonstrating that high polarity/TPSA does not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Brigatinib, structurally very close to the query (piperazine, aniline, pyrimidine, phosphine oxide), had 46% absolute oral bioavailability in healthy volunteers, directly supporting F >=20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "The same close analogue in the fasted state had 57% absolute bioavailability, confirming high F independent of prandial state.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Rifapentine, a large macrocyclic piperazine-containing drug, has 70% oral bioavailability in humans, supporting that piperazine/basic amine and high MW do not necessarily cause low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Paliperidone extended-release had 28% absolute oral bioavailability in humans, still above the 20% threshold, supporting high prediction despite moderate F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Encainide, a basic piperidine-containing drug, had 76±17% oral bioavailability in cirrhotic patients, supporting high F for ionizable amines.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer human absolute bioavailability measurements from close analogues (77%, 57%, 46%, 70%, 28%, ~100%) consistently exceed the 20% threshold, overriding the uncertain physicochemical prior. Low-F examples have zero transferability and are not informative.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself; prediction relies on close analogues.",
    "The query's very low neutral fraction and high TPSA are physicochemical concerns, but high-transfer analogues with similar ionizable piperazine/azine cores show F >20%, so the prior is overridden.",
    "Food effect and exact formulation differences are not fully matched across all evidence records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

